SELECT CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND(AVG(i.quantity), 2) AS avg_quantity, ROUND(STDDEV(i.quantity), 2) AS stddev_quantity FROM inventory i LEFT JOIN products p ON i.product_id = p.id JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END ORDER BY rating_bucket ASC;
